// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v, uint256 _decimals) public {
        vm.assume(_tos.length > 0);
        vm.assume(_decimals <= 76);
        vm.assume(v == 0 || _decimals == 0 || v <= type(uint256).max / (10 ** _decimals));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        bool ret;
        try c.transfer(from, caddress, _tos, v, _decimals) returns (bool result) {
            ret = result;
        } catch {
            return;
        }
        assertTrue(ret);
    }
}
